# cartesian_product :: ([1, 2], ['a', 'b'])
from itertools import product

def cartesian_product(a, b):
    return [(x, y) for x, y in product(a, b)]

if __name__ == "__main__":
    print(cartesian_product(([1, 2], ['a', 'b'])))

